//! Hack Antialiased Font -- crisp 8-bit alpha glyph data for KnoxOS
//!
//! Each pixel is an 8-bit alpha coverage value (0=transparent, 255=opaque).
//! Generated using exact area-coverage rasterization from 1-bit Hack bitmaps.
//! Interior pixels are fully opaque; only edge pixels have fractional alpha.
//!
//!   Standard: 10x20 pixels
//!   Compact:  8x14 pixels
pub const GLYPH_WIDTH: usize = 10;
pub const GLYPH_HEIGHT: usize = 20;
pub const GLYPH_WIDTH_COMPACT: usize = 8;
pub const GLYPH_HEIGHT_COMPACT: usize = 14;

const GLYPH_COUNT: usize = 95;

pub fn get_glyph(ch: char) -> Option<&'static [[u8; GLYPH_WIDTH]; GLYPH_HEIGHT]> {
    let idx = ch as usize;
    if (0x20..=0x7E).contains(&idx) {
        Some(&HACK_AA_STANDARD[idx - 0x20])
    } else {
        None
    }
}

pub fn get_glyph_compact(
    ch: char,
) -> Option<&'static [[u8; GLYPH_WIDTH_COMPACT]; GLYPH_HEIGHT_COMPACT]> {
    let idx = ch as usize;
    if (0x20..=0x7E).contains(&idx) {
        Some(&HACK_AA_COMPACT[idx - 0x20])
    } else {
        None
    }
}

